export const THEME_CSS: string = "/* Тема фреймворку та контракти компонентів ui-kit.\n *\n * Це ЧИСТИЙ CSS — тут навмисно немає ні `@import \"tailwindcss\"`, ні `@source`,\n * ні `@plugin \"daisyui\"`, ні імпортів з npm. Причина: файл їде у складі пакета\n * `client`, а збірка Tailwind належить застосунку. Директиви тут означали б, що\n * бібліотека компілює стилі за застосунок і сканує його каталоги — раніше саме\n * так і було (`@source \"../../app\"` усередині `client/`), і це був вихід за межі\n * пакета, якого `check:deps` не бачить: він обходить лише `.ts`.\n *\n * Підключає цей файл вхід збірки застосунку — `app/styles/tailwind.css`, останнім\n * рядком, тобто ПІСЛЯ Tailwind і daisyUI. Порядок обов'язковий: правила нижче\n * написані поза `@layer` і мусять перебивати шар utilities.\n *\n * Шрифт задається змінною `--default-font-family`, а самі файли шрифту підключає\n * застосунок: `@fontsource/*` резолвиться через node_modules, яких у пакета немає.\n */\n\n/* ── 1С тема (гамма перенесена з altera_danet) ─────────── */\n[data-theme=\"1c\"],\n:root,\n:host {\n  /* DaisyUI цвета — холодні сіро-блакитні тони altera_danet */\n  --color-primary:          #2f5f8f;\n  --color-primary-content:  #ffffff;\n  --color-secondary:        #4a7ab5;\n  --color-secondary-content:#ffffff;\n  --color-accent:           #2f5f8f;\n  --color-accent-content:   #ffffff;\n  --color-neutral:          #617482;\n  --color-neutral-content:  #ffffff;\n  --color-base-100:         #ffffff;\n  --color-base-200:         #dfe5ea;\n  --color-base-300:         #b8c3cc;\n  --color-base-content:     #243746;\n  --color-info:             #2f5f8f;\n  --color-info-content:     #ffffff;\n  --color-success:          #2d8a57;\n  --color-warning:          #f59e0b;\n  --color-error:            #ef4444;\n\n  /* Семантичні токени altera_danet — для майбутніх компонентів */\n  --app-bg:             #dfe5ea;\n  --app-surface:        #f6f8fa;\n  --app-surface-strong: #ffffff;\n  --app-header:         #e7edf2;\n  --app-border:         #b8c3cc;\n  --app-border-strong:  #98a7b4;\n  --app-text:           #243746;\n  --app-text-muted:     #617482;\n  --app-accent:         #2f5f8f;\n  --app-accent-soft:    #dfe8f1;\n\n  /* Радиусы — плоский стиль как в 1С (не частина гами) */\n  --radius-field:   2px;\n  --radius-box:     2px;\n  --radius-btn:     2px;\n  --radius-badge:   2px;\n\n  /* Структурні змінні daisyUI. Плагін підключено з `themes: false` (тема — цей\n     файл), а компоненти daisyUI (checkbox, radio, toggle, select…) спираються\n     на ці змінні БЕЗ фолбеків: невизначений `--border` анулює всю декларацію\n     рамки, і разом з `appearance: none` контрол стає невидимим — саме так\n     зникали чекбокси. Значення — під плоский стиль 1С: без глибини й шуму. */\n  --border:          1px;\n  --size-selector:   0.25rem;\n  --size-field:      0.25rem;\n  --radius-selector: 2px;\n  --depth:           0;\n  --noise:           0;\n\n  /* Шрифт */\n  --default-font-family: \"Roboto\", sans-serif;\n  --default-font-size:   0.875rem;\n}\n\n/* ── Глобальный сброс ────────────────────────────────── */\n*, *::before, *::after { box-sizing: border-box; }\n\nhtml, body {\n  font-size: var(--default-font-size);\n  background: var(--color-base-200);\n  color: var(--color-base-content);\n  font-family: var(--default-font-family);\n}\n\n/* ── Компактность компонентов ────────────────────────── */\n\n/* Кнопки — плоские, компактные */\n.btn {\n  font-size: var(--default-font-size);\n  height: 24px;\n  min-height: 24px;\n  padding-inline: 10px;\n  border-radius: var(--radius-btn);\n  font-weight: 400;\n  border: 1px solid var(--app-border);\n  background: #f5f7fa;\n  color: var(--app-text);\n}\n.btn:hover { background: #e3eaf3; }\n.btn-primary {\n  background: var(--color-primary);\n  color: var(--color-primary-content);\n  border-color: #244b71;\n}\n.btn-primary:hover { background: #244b71; }\n\n/* Инпуты */\n.input, .select, .textarea {\n  font-size: var(--default-font-size);\n  height: 24px;\n  min-height: 24px;\n  padding-inline: 6px;\n  border-radius: var(--radius-field);\n  border: 1px solid var(--app-border);\n  background: var(--app-surface-strong);\n}\n.input:focus, .select:focus, .textarea:focus {\n  outline: 1px solid var(--color-primary);\n  border-color: var(--color-primary);\n}\n/* Коли input всередині join — outline на весь join, не на input */\n.join:focus-within {\n  outline: 1px solid var(--color-primary);\n  border-radius: var(--radius-field);\n}\n.join .input:focus,\n.join .input:focus-within {\n  outline: none;\n  border-color: var(--color-primary);\n}\n\n/* Label */\n.label { padding: 1px 0; }\n.label-text { font-size: var(--default-font-size); color: var(--app-text-muted); }\n/* Legacy: .form-control — клас daisyUI 4, у 5-й версії його немає. Лишився\n   тільки для редактора шаблонів друку; у формах моделей використовуй\n   BaseUI.renderField() — він дає ту саму розкладку, що ui-picker/ui-date. */\n.form-control { margin-bottom: 6px; }\n\n/* Таблицы — сетка как в 1С */\n.table {\n  font-size: var(--default-font-size);\n  border-collapse: collapse;\n  background: var(--app-surface-strong, #ffffff);\n}\n.table :not(thead, tfoot) tr {\n  font-size: var(--default-font-size);\n}\n.table th {\n  background: #e3eaf0;\n  color: #354a59;\n  font-weight: 500;\n  padding: 3px 8px;\n  border: 1px solid var(--app-border);\n  font-size: var(--default-font-size);\n}\n.table td {\n  padding: 3px 8px;\n  border: 1px solid #d9e0e6;\n  line-height: 1.4;\n}\n.table tr.hover:hover td,\n.table-zebra tbody tr:hover td {\n  background: #dcebf8;\n  cursor: pointer;\n}\n.table-zebra tbody tr:nth-child(even) td {\n  background: #fbfcfd;\n}\n\n/* Join — групування елементів в один блок */\n.join { display: flex; align-items: stretch; }\n.join .join-item {\n  border-radius: 0 !important;\n  margin-inline-start: -1px;\n}\n.join .join-item:first-child { border-radius: var(--radius-field) 0 0 var(--radius-field) !important; margin-inline-start: 0; }\n.join .join-item:last-child  { border-radius: 0 var(--radius-field) var(--radius-field) 0 !important; }\n.join .join-item:only-child  { border-radius: var(--radius-field) !important; margin-inline-start: 0; }\n.join .join-item:focus,\n.join .join-item:focus-within { position: relative; z-index: 1; }\n\n/* ── Табличні частини документів ──────────────────────────\n   Контракт (перенесено з altera_danet, .app-table--tabular-section):\n   сітку малює ТІЛЬКИ таблиця, контрол у комірці не має власної рамки,\n   заокруглень, тіні й фону та займає комірку цілком.\n\n   Правила живуть тут, а не в компонентах, бо цей лист адоптується в кожен\n   shadow root (GlobalStyledLitElement) — отже дістає і до контролів усередині\n   ui-decimal / ui-picker.\n\n   ВАЖЛИВО: блок має йти ПІСЛЯ .input/.join/.table і теж поза @layer.\n   Утиліти Tailwind (шар utilities) тут не працюють — безшарові правила теми\n   перебивають будь-який шар незалежно від специфічності. */\n\n.table-tabular td {\n  padding: 0;\n  vertical-align: middle;\n}\n/* Текстові комірки (номер рядка, сума): горизонтальний відступ для читабельності,\n   вертикальний — нуль, інакше рядок стане вищим за контрол. */\n.table-tabular td.cell-text { padding: 0 8px; }\n\n.cell-control,\n.cell-control input,\n.cell-control .input,\n.cell-control .btn {\n  height: 24px;\n  min-height: 24px;\n  border: 0;\n  border-radius: 0 !important;\n  background: transparent;\n  box-shadow: none;\n}\n\n/* Контрол займає комірку по ширині (кнопки — фіксовані, див. нижче). */\n.cell-control,\n.cell-control input { width: 100%; }\n\n/* Рамки фокуса в комірці немає — межу малює сама таблиця (як в altera_danet). */\n.cell-control:focus,\n.cell-control input:focus,\n.cell-control .input:focus,\n.cell-control.join:focus-within,\n.cell-control .join-item:focus,\n.cell-control .join-item:focus-within {\n  outline: none;\n  border-color: transparent;\n}\n\n/* Іконкові кнопки в комірці — рівно 24×24 без падінгів. */\n.cell-control .btn {\n  width: 24px;\n  min-width: 24px;\n  padding-inline: 0;\n}\n\n/* Загрузка */\n.loading { width: 16px; height: 16px; }\n\n/* ── Діалоги застосунку ───────────────────────────────────────────────────\n   Спільний контракт модального вікна (confirm-host, вибір групи, будь-які\n   майбутні діалоги): «вікно 1С» — смуга заголовка кольору оболонки з\n   хрестиком, біле тіло, підвал дій на сірому. Живе в темі, бо лист\n   адоптується в кожен shadow root — діалог будь-якого компонента виглядає\n   однаково, без копіювання стилів. */\n.app-dialog-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 60;\n  display: grid;\n  place-items: center;\n  background: rgba(36, 55, 70, .45);\n}\n.app-dialog {\n  background: var(--color-base-100, #ffffff);\n  border: 1px solid var(--app-border-strong, #98a7b4);\n  border-radius: var(--radius-box, 2px);\n  box-shadow: 0 12px 40px rgba(0, 0, 0, .35);\n  min-width: 20rem;\n  max-width: 32rem;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n.app-dialog-title {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 5px 8px 5px 10px;\n  background: var(--color-primary, #2f5f8f);\n  color: var(--color-primary-content, #ffffff);\n  font-weight: 500;\n  user-select: none;\n}\n.app-dialog-close {\n  cursor: pointer;\n  opacity: .75;\n  font-size: 15px;\n  line-height: 1;\n  padding: 2px 5px;\n  border-radius: 2px;\n}\n.app-dialog-close:hover { opacity: 1; background: rgba(255, 255, 255, .18); }\n.app-dialog-body { padding: 12px; }\n.app-dialog-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 8px 10px;\n  background: var(--app-header, #e7edf2);\n  border-top: 1px solid var(--app-border, #b8c3cc);\n}\n\n/* ─── Друк ────────────────────────────────────────────────────────────────\n   Правила рівня компонента: цей лист адоптується в кожен shadow root, тож\n   `.no-print`/`.print-only` працюють усередині форм. Розкладку документа й\n   оболонки задають інші два рівні — див. `client/ui-kit/report/print.ts`.\n\n   `.print-only` за замовчуванням схований — блок «назва звіту, організація,\n   період» потрібен лише на папері: на екрані те саме видно в тулбарі. */\n.print-only { display: none; }\n.print-title { font-size: 15px; font-weight: 700; margin: 0 0 2px; }\n.print-subtitle { font-size: 12px; color: #444; margin: 0; }\n\n/* ─── Графік у звіті ──────────────────────────────────────────────────────\n   Фреймворк графіків не малює — чим саме, вирішує застосунок. Але місце для\n   нього описане тут, бо з друком і експортом графік стикається однаково,\n   незалежно від бібліотеки.\n\n   Контракт: полотно чи SVG кладуть у `.report-chart`. Маркер потрібен саме\n   тому, що правила не можна повісити на `canvas, svg` взагалі — під `svg`\n   потрапили б і вбудовані іконки в комірках.\n\n   В Excel графік не потрапляє: аркуш читається з таблиці, а графік — не\n   таблиця. Якщо він усе-таки живе всередині `<table>` (рядок на всю ширину),\n   позначте цей рядок `no-export` — див. `client/ui-kit/report/table-model.ts`. */\n.report-chart { break-inside: avoid; }\n.report-chart canvas,\n.report-chart svg { max-width: 100%; height: auto; }\n\n@media print {\n  .no-print { display: none !important; }\n  .print-only { display: block !important; }\n\n  /* Фон шапки таблиці браузер за замовчуванням не друкує — без цього сітка\n     звіту на папері розсипається на однакові білі клітинки. */\n  .table th {\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n  }\n  .table th,\n  .table td {\n    padding: 2px 4px;\n    font-size: 9px;\n  }\n\n  /* Шапка повторюється на кожній сторінці (це стандартна поведінка thead,\n     але лише коли таблиця не всередині контейнера з прокруткою — його\n     розтискає рівень оболонки). Рядок не розривається між сторінками. */\n  thead { display: table-header-group; }\n  tfoot { display: table-footer-group; }\n  tr, td, th { break-inside: avoid; }\n\n  /* Посилання (рахунок, документ, субконто) на папері — звичайний текст:\n     підкреслення й колір там означають лише зайвий шум. */\n  .link, .btn.link, button.link {\n    color: inherit !important;\n    text-decoration: none !important;\n  }\n\n  /* Графік на папері. Три різні біди, і кожну лікує свій рядок:\n       · `break-inside` — інакше графік розсікається межею сторінки навпіл;\n       · `max-width` + `height: auto` — вписати в поля, зберігши пропорції.\n         Саме max-width, а не width: графік, вужчий за сторінку, не треба\n         розтягувати — від цього полотно тільки замилюється;\n       · `print-color-adjust` — браузер за замовчуванням не друкує заливки, і\n         стовпчикова діаграма виходить із самих контурів. Та сама причина, що\n         й у шапки таблиці вище. */\n  .report-chart {\n    break-inside: avoid;\n    page-break-inside: avoid;\n  }\n  .report-chart canvas,\n  .report-chart svg {\n    max-width: 100% !important;\n    height: auto !important;\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n  }\n}\n";
